async function pastePromptSection(id,label='当前'){const field=$(id);if(!field)return;try{if(!navigator.clipboard?.readText)throw Error('当前浏览器不支持直接读取剪贴板');const text=(await navigator.clipboard.readText()).trim();if(!text){$('tokenHint').textContent='剪贴板中没有可粘贴的文字。';return}field.value=text;tokenHistory=tokenHistory.filter(item=>item.field!==id);promptEditorChanged();field.focus();$('tokenHint').textContent=`已从剪贴板填入${label}分区`}catch(e){$('tokenHint').textContent='无法读取剪贴板：请允许此页面访问剪贴板，或在输入框中按 Ctrl+V。'}}
function normalizedClientTerm(value){return String(value||'').trim().toLowerCase().replace(/\\([()])/g,'$1').replace(/_/g,' ').replace(/\s+/g,' ').replace(/^\((.*):\s*[0-2](?:\.\d+)?\)$/,'$1').replace(/[ .]+$/,'')}
