function renderTokens(){const root=$('tokenGroups'),tabs=$('tokenCategoryTabs'),search=$('tokenSearch');if(!root)return;const query=String(search?.value||'').trim().toLowerCase(),groups=Object.entries(tokenLibrary);if(!tokenLibrary[activeTokenGroup])activeTokenGroup=groups[0]?.[0]||'';if(tabs){tabs.innerHTML='';groups.forEach(([group,items])=>{const button=document.createElement('button');button.type='button';button.className='token-category'+(!query&&group===activeTokenGroup?' active':'');button.textContent=group;button.title=`${items.length} 个快捷词`;button.onclick=()=>selectTokenGroup(group);tabs.appendChild(button)})}root.innerHTML='';const visible=query?groups.map(([group,items])=>[group,items.filter(([zh,en])=>(zh+' '+en).toLowerCase().includes(query))]).filter(([,items])=>items.length):groups.filter(([group])=>group===activeTokenGroup);visible.forEach(([group,items])=>{const box=document.createElement('section');box.className='token-group';box.innerHTML=`<div class="group-name"><b>${esc(group)}</b><span>${items.length} 个</span></div><div class="tokens"></div>`;const list=box.querySelector('.tokens');items.forEach(([zh,en,section='manual'])=>{const b=document.createElement('button');b.className='token';b.type='button';b.textContent=zh;b.title=en;b.onclick=()=>appendToken(en,zh,b,section);list.appendChild(b)});if(!query&&cascadeLibrary[group])renderCascades(box,cascadeLibrary[group],group);root.appendChild(box)});if(!visible.length)root.innerHTML='<div class="token-empty">没有匹配的快捷词，可尝试中文或英文标签。</div>';if(query&&$('tokenHint'))$('tokenHint').textContent=`搜索“${search.value.trim()}”：${visible.reduce((sum,[,items])=>sum+items.length,0)} 个结果`}
