function deepSeekWebInstruction(text){const family=promptFamilyClient(),checkpoint=$('model')?.value||'未选择',safety=$('safetyLevel')?.value||'safe',familyRules={anima:'以 Danbooru 英文硬标签为主，补充简短英文关系句；不要凭空添加角色、服装或动作；不要添加与模型 LoRA 冲突的质量前缀。',illustrious:'以逗号分隔的 Danbooru 英文标签为主，主体、外貌、服装、动作、构图、场景、光影顺序清楚。',sdxl:'使用清晰、简洁的英文图像提示词，标签为主，必要时用短句消除动作或空间歧义。',krea2:'使用自然流畅的英文视觉描述，明确主体、动作、镜头、场景、光影和材质，避免标签堆砌。'};return`你是 ComfyUI 提示词转换助手。请把下面的中文构想转换成适合当前模型的英文提示词。\n当前模型族：${translationFamilyLabel(family)}\n当前检查点：${checkpoint}\n安全级别：${safety}\n规则：${familyRules[family]||familyRules.sdxl}\n保留用户明确要求，不扩写敏感程度，不解释思路，不使用 Markdown 代码块。只按以下两行格式回答：\nPOSITIVE: 英文正向提示词\nNEGATIVE: 仅列出针对本画面需要额外避免的问题；没有则留空\n\n用户中文构想：\n${text}`}
async function copyDeepSeekInstruction(value){const text=String(value||'');if(!text)throw Error('复制内容为空');if(text.length>65536)throw Error('复制内容过长');if(window.EasyPanelClipboard&&typeof window.EasyPanelClipboard.copyText==='function'){try{if(window.EasyPanelClipboard.copyText(text)===true)return}catch(e){}}if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);return}const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.focus();area.select();try{if(!document.execCommand('copy'))throw Error('浏览器拒绝复制')}finally{area.remove()}}
function hideDeepSeekManualInstruction(){const area=$('deepSeekManualInstruction'),help=$('deepSeekManualHelp');if(area){area.value='';area.style.display='none'}if(help)help.style.display='none'}
function showDeepSeekManualInstruction(value){const area=$('deepSeekManualInstruction'),help=$('deepSeekManualHelp');if(area){area.value=String(value||'');area.style.display='block'}if(help)help.style.display='block'}
async function sharedPromptInstruction(text){try{const response=await fetch('/api/prompt-instruction',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,model:$('model')?.value||'',safetyLevel:$('safetyLevel')?.value||'safe'})}),data=await response.json();if(!response.ok||data.error||!data.instruction)throw Error(data.error||'服务器未返回提示词转换指令');const family=data.family||promptFamilyClient();return{instruction:data.instruction,family,familyLabel:data.family_label||translationFamilyLabel(family),model:data.model||$('model')?.value||'未选择'}}catch{const family=promptFamilyClient();return{instruction:deepSeekWebInstruction(text),family,familyLabel:translationFamilyLabel(family),model:$('model')?.value||'未选择'}}}
async function copyDeepSeekInstructionManually(){const text=$('zhPrompt').value.trim();if(!text){hideDeepSeekManualInstruction();$('translationResult').textContent='请先输入中文描述。';return}const converted=await sharedPromptInstruction(text),instruction=converted.instruction;try{await copyDeepSeekInstruction(instruction);hideDeepSeekManualInstruction();$('deepSeekManualCopy')?.style.setProperty('display','none');$('translationResult').textContent='已复制转换指令。请切换到 DeepSeek 后粘贴发送。'}catch(e){showDeepSeekManualInstruction(instruction);$('deepSeekManualCopy')?.style.setProperty('display','inline-block');$('translationResult').textContent='自动复制仍未成功，已显示完整转换指令。请长按下方文本区域，全选并复制。'}}
async function openDeepSeekWeb(){const text=$('zhPrompt').value.trim();if(!text){hideDeepSeekManualInstruction();$('translationResult').textContent='请先输入中文描述。';return}const converted=await sharedPromptInstruction(text),instruction=converted.instruction;try{await copyDeepSeekInstruction(instruction);hideDeepSeekManualInstruction();$('deepSeekManualCopy')?.style.setProperty('display','none');$('translationResult').textContent=`已复制【${converted.familyLabel}】转换指令，正在打开 DeepSeek。请在 DeepSeek 中粘贴并发送，复制回答后回到这里点“读取 DeepSeek 回答”。`;window.open('https://chat.deepseek.com/','_blank','noopener,noreferrer')}catch(e){showDeepSeekManualInstruction(instruction);const manual=$('deepSeekManualCopy');if(manual)manual.style.display='inline-block';$('translationResult').textContent='自动复制失败，DeepSeek 尚未打开。已显示完整转换指令，请点击“复制失败？手动复制指令”重试，或长按文本区域全选复制。'}}
async function readDeepSeekClipboard(){try{if(!navigator.clipboard?.readText)throw Error('浏览器不支持读取剪贴板');let raw=(await navigator.clipboard.readText()).trim();if(!raw){$('translationResult').textContent='剪贴板为空，请先复制 DeepSeek 的回答。';return}raw=raw.replace(/```(?:text|json)?/gi,'').replace(/```/g,'').trim();const positiveMatch=raw.match(/(?:^|\n)\s*POSITIVE\s*[:：]\s*([\s\S]*?)(?=\n\s*NEGATIVE\s*[:：]|$)/i),negativeMatch=raw.match(/(?:^|\n)\s*NEGATIVE\s*[:：]\s*([\s\S]*)$/i);const positive=(positiveMatch?positiveMatch[1]:raw).trim(),negative=(negativeMatch?negativeMatch[1]:'').trim();translated={positive,negative,family:promptFamilyClient(),promptMode:'flat',sections:{}};$('translatedPositive').textContent=positive||'（未识别到正向提示词）';$('translatedNegative').textContent=negative||'（无额外负面词）';$('translationPreview').style.display='block';$('translationResult').textContent='已读取 DeepSeek 回答；请检查后加入正向或负面提示词。'}catch(e){$('translationResult').textContent='无法读取剪贴板：请允许权限，或把 DeepSeek 回答手动粘贴到提示词框。'}}
function translateAI(){return openDeepSeekWeb()}
async function translateGoogle(){const text=$('zhPrompt').value.trim(),key=$('googleKey').value.trim();if(!text){$('translationResult').textContent='请先输入中文描述。';return}if(!key){$('translationResult').textContent='请填写 Google Cloud Translation API Key。';return}$('translationResult').textContent='Google 正在翻译…';$('translationPreview').style.display='none';try{const r=await fetch('/api/google-translate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,apiKey:key})}),data=await r.json();if(data.error)throw Error(data.error);translated={positive:data.positive||'',negative:'',sections:data.sections||{naturalLanguage:data.positive||''}};$('translatedPositive').textContent=translated.positive||'（未返回英文结果）';$('translatedNegative').textContent='（Google 直译会写入自然语言分区）';$('translationPreview').style.display='block';$('translationResult').textContent='Google 直译完成：确认后写入自然语言分区。'}catch(e){$('translationResult').textContent='Google 翻译失败：'+e.message}}
function mergeNaturalLanguage(value){const field=$('promptNaturalLanguage'),text=String(value||'').trim();if(!text||field.value.includes(text))return false;field.value=field.value.trim()?field.value.trim()+' '+text:text;promptEditorChanged();return true}
function appendNegative(value){const incoming=splitClientTerms(value),existing=splitClientTerms($('negative').value),known=new Set(existing.map(normalizedClientTerm));let changed=false;incoming.forEach(term=>{const key=normalizedClientTerm(term);if(key&&!known.has(key)){known.add(key);existing.push(term);changed=true}});if(changed){$('negative').value=existing.join(', ');promptEditorChanged()}return changed}
function applyTranslated(kind){if(kind==='negative'){appendNegative(translated.negative);$('negative').focus();return}const sections=translated.sections||{};if(Object.keys(sections).length){Object.entries(sections).forEach(([key,value])=>{if(key==='naturalLanguage')mergeNaturalLanguage(value);else if(value)appendEnglish(value,key)});if(!Object.keys(sections).length&&translated.positive)appendEnglish(translated.positive,'manual');$('translationResult').textContent='已按人物、外貌、服装、姿势、构图、场景、光线和画风分区写入。';return}const text=(translated.positive||'').trim();if(!text){$('translationResult').textContent='没有可加入的正向提示词。';return}const field=$('prompt');field.value=field.value.trim()?field.value.trim()+', '+text:text;promptEditorChanged();field.focus();$('translationResult').textContent=`已按【${translationFamilyLabel(translated.family||promptFamilyClient())}】生成完整正向提示词并写入手动补充。`}
function undoToken(){const last=tokenHistory.pop();if(!last)return;const field=$(last.field);if(!field)return;const remove=new Set((last.terms||[]).map(normalizedClientTerm));field.value=splitClientTerms(field.value).filter(term=>!remove.has(normalizedClientTerm(term))).join(', ');$('tokenHint').textContent='已撤销上一项';promptEditorChanged()}
