let tagTimer;async function searchTags(){clearTimeout(tagTimer);const input=$('tagSearch').value.trim();const root=$('tagResults');if(!input){root.innerHTML='<span class="small">输入内容后显示候选；点击即可插入规范英文标签。</span>';return}tagTimer=setTimeout(async()=>{try{const data=await(await fetch('/api/tags?q='+encodeURIComponent(input))).json();root.innerHTML=data.tags.length?'':'<span class="small">没有找到匹配标签。</span>';data.tags.forEach(item=>{const b=document.createElement('button');b.className='token';b.type='button';b.innerHTML=`${esc(item.tag)} <small>${esc(item.translation||item.category)} · ${item.count.toLocaleString()}</small>`;b.title=`${item.category}${item.translation?'：'+item.translation:''}`;b.onclick=()=>{const section=$('tagTarget').value;appendEnglish(item.tag,section);$('tagSearch').value='';root.innerHTML='<span class="small">已插入到'+sectionLabel(section)+'：'+esc(item.tag)+'</span>'};root.appendChild(b)});}catch(e){root.innerHTML='<span class="small">标签库读取失败：'+esc(e.message)+'</span>'}},180)}
function updateCount(){const ids=[...new Set(Object.values(PROMPT_SECTION_IDS))],total=ids.reduce((sum,id)=>sum+splitClientTerms($(id)?.value).length,0);$('promptCount').textContent=total+' 个内容标签'}
function noteKey(name){return String(name||'').replace(/\\/g,'/').replace(/^\.\//,'')}
function noteBaseKey(name){return noteKey(name).split('/').pop()}
function noteLookupKey(name){const full=noteKey(name),base=noteBaseKey(name);return Object.prototype.hasOwnProperty.call(loraNotes,full)?full:base}
function loraNoteForName(name){return loraNotes[noteKey(name)]||loraNotes[noteBaseKey(name)]||{}}
function sidecarKey(name){return String(name||'').replace(/\\/g,'/').replace(/\.safetensors$/i,'')}
function selectedSidecar(){return loraSidecars[sidecarKey(currentLoraName)]||null}
function loadLoraFavorites(){try{const saved=JSON.parse(localStorage.getItem(LORA_FAVORITES_STORAGE)||'[]');loraFavorites=new Set(Array.isArray(saved)?saved.filter(name=>typeof name==='string'&&name):[])}catch{loraFavorites=new Set()}if(!loraAliasLoadPromise)queueMicrotask(loadLoraRenameAliases)}
function saveLoraFavorites(){try{localStorage.setItem(LORA_FAVORITES_STORAGE,JSON.stringify([...loraFavorites].sort()))}catch{}}
function renamedLoraName(name){const original=String(name||''),normalized=noteKey(original),renamed=loraRenameAliases[normalized]||loraRenameAliases[noteBaseKey(normalized)];if(!renamed)return original;return original.includes('\\')?renamed.replace(/\//g,'\\'):renamed}
function migrateStoredLoraNames(){try{const saved=JSON.parse(localStorage.getItem(LORA_FAVORITES_STORAGE)||'[]');if(Array.isArray(saved)){const migrated=[...new Set(saved.filter(name=>typeof name==='string'&&name).map(renamedLoraName))];localStorage.setItem(LORA_FAVORITES_STORAGE,JSON.stringify(migrated.sort()))}}catch{}try{const saved=JSON.parse(sessionStorage.getItem(LORA_STATE_STORAGE)||'[]');if(Array.isArray(saved))sessionStorage.setItem(LORA_STATE_STORAGE,JSON.stringify(saved.map(item=>item&&typeof item==='object'?{...item,name:renamedLoraName(item.name)}:item)))}catch{}try{appliedOutfits=appliedOutfits.map(preset=>preset&&typeof preset==='object'?{...preset,key:renamedLoraName(preset.key)}:preset);if(appliedOutfits.length)sessionStorage.setItem('easyPanelAppliedOutfits',JSON.stringify(appliedOutfits))}catch{}loadLoraFavorites()}
function reconcileStoredLoraNamesWithCatalog(){const available=listOrEmpty(catalog.loras);if(!available.length)return;const actualByNormalized=new Map(available.map(name=>[noteKey(name).toLocaleLowerCase(),name])),actual=name=>actualByNormalized.get(noteKey(name).toLocaleLowerCase())||name;try{loraFavorites=new Set([...loraFavorites].map(actual));saveLoraFavorites()}catch{}try{const saved=JSON.parse(sessionStorage.getItem(LORA_STATE_STORAGE)||'[]');if(Array.isArray(saved))sessionStorage.setItem(LORA_STATE_STORAGE,JSON.stringify(saved.map(item=>item&&typeof item==='object'?{...item,name:actual(item.name)}:item)))}catch{}}
async function loadLoraRenameAliases(){if(loraAliasLoadPromise)return loraAliasLoadPromise;loraAliasLoadPromise=(async()=>{try{const data=await(await fetch('/api/lora-aliases')).json();loraRenameAliases=data.aliases&&typeof data.aliases==='object'?data.aliases:{};migrateStoredLoraNames();if(listOrEmpty(catalog.loras).length){renderLoraFolderOptions();restoreLoraState();refreshLoraSelects()}}catch{loraRenameAliases={}}})();return loraAliasLoadPromise}
function validFavoriteLoras(){const available=new Set(listOrEmpty(catalog.loras));return [...loraFavorites].filter(name=>available.has(name))}
function loraFavoriteFolder(name){return(catalog.loraMeta?.[name]?.folder||'未分类').trim()||'未分类'}
function favoriteFolderValue(folder){return'__favorite_folder__:'+encodeURIComponent(folder)}
function favoriteFolderFromValue(value){if(!String(value).startsWith('__favorite_folder__:'))return'';try{return decodeURIComponent(String(value).slice(20))}catch{return''}}
function loraFolderOptions(){const folders=new Set();Object.values(catalog.loraMeta||{}).forEach(m=>{if(m&&m.folder&&loraFamilyVisible(m.family))folders.add(m.folder)});const favorites=validFavoriteLoras(),favoriteCounts={};favorites.forEach(name=>{const folder=loraFavoriteFolder(name);favoriteCounts[folder]=(favoriteCounts[folder]||0)+1});const favoriteOptions=favorites.length?`<optgroup label="★ 我的收藏"><option value="__favorites__">★ 全部收藏（${favorites.length}）</option>${Object.keys(favoriteCounts).sort().map(folder=>`<option value="${esc(favoriteFolderValue(folder))}">★ ${esc(folder)}（${favoriteCounts[folder]}）</option>`).join('')}</optgroup>`:'';return '<option value="">当前模型族 · 全部文件夹</option>'+favoriteOptions+`<optgroup label="当前模型族 LoRA 分类">${[...folders].sort().map(f=>`<option value="${esc(f)}">${esc(f)}</option>`).join('')}</optgroup>`}
function renderLoraFolderOptions(){reconcileStoredLoraNamesWithCatalog();const select=$('loraFolder');if(!select)return;const current=select.value;select.innerHTML=loraFolderOptions();if([...select.options].some(option=>option.value===current))select.value=current;else if(current.startsWith('__favorite')&&validFavoriteLoras().length)select.value='__favorites__';else select.value='';const count=$('loraFavoriteCount');if(count)count.textContent=String(validFavoriteLoras().length)}
function loraFamilyVisible(family){return String(family||'general').toLocaleLowerCase()===promptFamilyClient()}
function loraSearchTerms(){return String($('loraSearch')?.value||'').normalize('NFKC').toLocaleLowerCase().trim().split(/\s+/).filter(Boolean)}
function loraMatchesSearch(name,meta={}){const terms=loraSearchTerms();if(!terms.length)return true;const searchable=[name,meta.folder||'',String(name).replace(/[\\/_.\-]+/g,' ')].join(' ').normalize('NFKC').toLocaleLowerCase();return terms.every(term=>searchable.includes(term))}
function filteredLoras(){const folder=$('loraFolder').value,meta=catalog.loraMeta||{},favoritesOnly=folder==='__favorites__'||folder.startsWith('__favorite_folder__:'),favoriteFolder=favoriteFolderFromValue(folder);return listOrEmpty(catalog.loras).filter(name=>{const m=meta[name]||{};if(favoritesOnly&&!loraFavorites.has(name))return false;if(favoriteFolder&&loraFavoriteFolder(name)!==favoriteFolder)return false;if(folder&&!favoritesOnly&&m.folder!==folder)return false;if(!loraMatchesSearch(name,m))return false;return favoritesOnly||loraFamilyVisible(m.family)})}
