function updateLoraFavoriteButton(button,name){const active=!!name&&loraFavorites.has(name);button.disabled=!name;button.classList.toggle('active',active);button.textContent=active?'★':'☆';button.title=!name?'请先选择 LoRA':active?'取消收藏此 LoRA':'收藏此 LoRA';button.setAttribute('aria-label',button.title);button.setAttribute('aria-pressed',String(active))}
