function refreshLoraSelects(){const list=filteredLoras(),favoriteMode=$('loraFolder').value.startsWith('__favorite'),meta=catalog.loraMeta||{};document.querySelectorAll('#loras select').forEach(sel=>{const cur=sel.value;sel.innerHTML=options(list,cur);if(cur&&!list.includes(cur)&&(favoriteMode||loraFamilyVisible(meta[cur]?.family))){const o=document.createElement('option');o.value=cur;o.textContent=cur;o.selected=true;sel.appendChild(o)}});syncLoraFavoriteButtons();const info=$('loraFilterInfo'),query=String($('loraSearch')?.value||'').trim();if(info)info.textContent=`${query?'搜索“'+query+'” · ':''}当前 ${list.length} 个 LoRA${favoriteMode?' · 收藏不受模型族限制':' · 仅当前模型族'}`;const quick=$('loraFavoritesQuick');if(quick)quick.classList.toggle('active',favoriteMode)}
function toggleLoraFavorite(name){if(!name)return;const adding=!loraFavorites.has(name);if(adding)loraFavorites.add(name);else loraFavorites.delete(name);saveLoraFavorites();renderLoraFolderOptions();refreshLoraSelects();$('status').textContent=adding?`已收藏 LoRA，并归入“${loraFavoriteFolder(name)}”分类。`:'已取消收藏此 LoRA。'}
