function embeddingFolderOptions(){const folders=[...new Set(Object.values(catalog.embeddingMeta||{}).map(item=>item?.folder).filter(Boolean))].sort();return '<option value="">全部分类</option>'+folders.map(folder=>`<option value="${esc(folder)}">${esc(embeddingFolderLabel(folder))}</option>`).join('')}
function renderEmbeddingFolderOptions(){const select=$('embeddingFolder');if(!select)return;const current=select.value;select.innerHTML=embeddingFolderOptions();if([...select.options].some(option=>option.value===current))select.value=current;else select.value=''}
function embeddingFamilyVisible(family){const current=promptFamilyClient();if(family==='illustrious')return current==='illustrious';if(family==='anima')return current==='anima';if(family==='krea2')return current==='krea2';return true}
function filteredEmbeddings(){const folder=$('embeddingFolder')?.value||'',meta=catalog.embeddingMeta||{};return listOrEmpty(catalog.embeddings).filter(name=>{const item=meta[name]||{};return(!folder||item.folder===folder)&&embeddingFamilyVisible(item.family)})}
