function updateEmbeddingInfo(){const name=$('embeddingSelect')?.value||'',item=(catalog.embeddingMeta||{})[name]||{},target=item.section==='negative'?'负面词':sectionLabel(item.section||'manual'),info=$('embeddingInfo');if(info)info.textContent=name?`${item.label||name} · 页面触发词：${item.trigger||name} · 点击应用后写入“${target}” · ${embeddingPromptToken(name)}`:`当前 ${filteredEmbeddings().length} 个可用 Embedding`}
