function allLoraState(){return[...$('loras').querySelectorAll('.lora-row')].map(row=>({name:row.querySelector('.lora-select').value,weight:row.querySelector('.lora-strength').value,enabled:row.dataset.enabled!=='false'})).filter(item=>item.name)}
function saveLoraState(){try{const items=allLoraState();if(items.length)sessionStorage.setItem(LORA_STATE_STORAGE,JSON.stringify(items));else sessionStorage.removeItem(LORA_STATE_STORAGE)}catch{}}
function restoreLoraState(){let saved=[];try{const value=JSON.parse(sessionStorage.getItem(LORA_STATE_STORAGE)||'[]');if(Array.isArray(value))saved=value}catch{}const meta=catalog.loraMeta||{},valid=saved.filter(item=>item&&catalog.loras.includes(item.name)&&loraFamilyVisible(meta[item.name]?.family)).slice(0,16),validKeys=new Set(valid.map(item=>noteKey(item.name))),orphaned=appliedOutfits.filter(p=>!validKeys.has(p.key));orphaned.forEach(p=>removeOutfitSections(p.item,p.state));if(orphaned.length)setAppliedOutfits(appliedOutfits.filter(p=>validKeys.has(p.key)));$('loras').innerHTML='';if(valid.length)valid.forEach(item=>addLora(item.name,String(item.weight??'0.70'),item.enabled!==false));else addLora();saveLoraState()}
function removeAppliedOutfitsForLora(name){const key=noteKey(name);if(!key)return 0;const removed=appliedOutfits.filter(p=>p.key===key),remaining=appliedOutfits.filter(p=>p.key!==key);removed.forEach(p=>removeOutfitSections(p.item,p.state));if(removed.length)setAppliedOutfits(remaining);return removed.length}
let draggedLoraRow=null,loraDragChanged=false;
function updateLoraOrderUi(){const rows=[...$('loras').querySelectorAll('.lora-row')];rows.forEach((row,index)=>{row.dataset.order=String(index+1);const handle=row.querySelector('.lora-drag-handle'),up=row.querySelector('.lora-move-up'),down=row.querySelector('.lora-move-down');if(handle){handle.textContent='↕'+(index+1);handle.title=`拖动调整 LoRA 顺序（当前第 ${index+1} 个）`;handle.setAttribute('aria-label',handle.title)}if(up)up.disabled=index===0;if(down)down.disabled=index===rows.length-1})}
function commitLoraOrder(message){updateLoraOrderUi();saveLoraState();renderRegions();promptEditorChanged();renderExperimentControls();if(message)$('status').textContent=message}
function moveLoraRow(row,direction){const sibling=direction<0?row.previousElementSibling:row.nextElementSibling;if(!sibling)return;if(direction<0)row.parentNode.insertBefore(row,sibling);else row.parentNode.insertBefore(sibling,row);commitLoraOrder(`已${direction<0?'上移':'下移'} LoRA；加载链和自动触发词顺序已同步。`)}
function finishLoraDrag(){if(!draggedLoraRow)return;draggedLoraRow.classList.remove('dragging');const changed=loraDragChanged;draggedLoraRow=null;loraDragChanged=false;if(changed)commitLoraOrder('已调整 LoRA 顺序；加载链和自动触发词顺序已同步。');else updateLoraOrderUi()}
function updateLoraEnabledUi(row,enabled){row.dataset.enabled=String(enabled);row.classList.toggle('lora-disabled',!enabled);const button=row.querySelector('.lora-enabled-toggle');if(button){button.textContent=enabled?'禁用':'恢复';button.title=enabled?'暂时禁用此 LoRA（保留在列表中）':'恢复此 LoRA 参与生成';button.setAttribute('aria-label',button.title);button.setAttribute('aria-pressed',String(!enabled))}}
function toggleLoraEnabled(row){const enabled=row.dataset.enabled==='false';updateLoraEnabledUi(row,enabled);saveLoraState();renderRegions();renderExperimentControls();promptEditorChanged();const name=row.querySelector('.lora-select')?.value||'当前 LoRA';$('status').textContent=enabled?`已恢复 ${name}，会参与后续生成。`:`已禁用 ${name}，仍保留在列表中但不会参与生成。`}
function addLora(name='',weight='0.70',enabled=true){const row=document.createElement('div');row.className='row lora-row';row.dataset.enabled=String(enabled!==false);const select=document.createElement('select');select.className='lora-select';let loraList=filteredLoras();if(name&&!loraList.includes(name))loraList=[name,...loraList];select.innerHTML=options(loraList,name);select.dataset.loraName=name;select.title=name||'请选择 LoRA';const activateMemo=()=>{const previous=select.dataset.loraName||'';select.title=select.value||'请选择 LoRA';if(previous!==select.value){removeAppliedOutfitsForLora(previous);select.dataset.loraName=select.value;saveLoraState()}selectLoraNote(select.value,select);renderRegions();renderExperimentControls();promptEditorChanged();updateLoraFavoriteButton(favorite,select.value)};select.onchange=activateMemo;select.oninput=activateMemo;select.onfocus=()=>selectLoraNote(select.value,select);select.onmousedown=()=>selectLoraNote(select.value,select);row.onclick=event=>{if(!event.target.closest('button,input'))selectLoraNote(select.value,select)};const strength=document.createElement('input');strength.className='lora-strength';strength.type='number';strength.min='0';strength.max='1.5';strength.step='0.05';strength.value=weight;strength.title='LoRA 权重：0.7–1.0 常规；越高角色特征越强，过高易过拟合/崩坏。';strength.oninput=()=>{saveLoraState();promptEditorChanged()};const controls=document.createElement('div');controls.className='lora-order-controls';const handle=document.createElement('button');handle.type='button';handle.className='lora-drag-handle';handle.draggable=true;handle.ondragstart=event=>{draggedLoraRow=row;loraDragChanged=false;row.classList.add('dragging');event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain','easy-panel-lora')};handle.ondragend=finishLoraDrag;const up=document.createElement('button');up.type='button';up.className='lora-move-up';up.textContent='↑';up.title='上移 LoRA';up.setAttribute('aria-label','上移 LoRA');up.onclick=()=>moveLoraRow(row,-1);const down=document.createElement('button');down.type='button';down.className='lora-move-down';down.textContent='↓';down.title='下移 LoRA';down.setAttribute('aria-label','下移 LoRA');down.onclick=()=>moveLoraRow(row,1);controls.append(handle,up,down);row.ondragover=event=>{if(!draggedLoraRow||draggedLoraRow===row)return;event.preventDefault();event.dataTransfer.dropEffect='move';const before=event.clientY<row.getBoundingClientRect().top+row.getBoundingClientRect().height/2,rowParent=row.parentNode;rowParent.insertBefore(draggedLoraRow,before?row:row.nextSibling);loraDragChanged=true;updateLoraOrderUi()};row.ondrop=event=>event.preventDefault();const favorite=document.createElement('button');favorite.type='button';favorite.className='lora-favorite';favorite.onclick=()=>toggleLoraFavorite(select.value);const enabledToggle=document.createElement('button');enabledToggle.type='button';enabledToggle.className='lora-enabled-toggle';enabledToggle.onclick=()=>toggleLoraEnabled(row);const remove=document.createElement('button');remove.type='button';remove.className='lora-remove';remove.title='移除';remove.setAttribute('aria-label','移除 LoRA');remove.textContent='×';remove.onclick=()=>{const wasActive=select.value===currentLoraName,removedPresets=removeAppliedOutfitsForLora(select.value);row.remove();updateLoraOrderUi();saveLoraState();renderRegions();renderExperimentControls();if(wasActive){const remaining=document.querySelector('#loras select');selectLoraNote(remaining?remaining.value:'',remaining)}else promptEditorChanged();$('status').textContent=removedPresets?'已移除 LoRA，并撤销它通过预设加入的提示词；手写内容已保留。':'已移除 LoRA。'};row.append(select,strength,controls,enabledToggle,favorite,remove);$('loras').appendChild(row);updateLoraEnabledUi(row,enabled!==false);updateLoraFavoriteButton(favorite,select.value);updateLoraOrderUi();if(name){selectLoraNote(name,select);saveLoraState()}else promptEditorChanged();renderRegions();renderExperimentControls();return row}
function clearLoras(){const removed=appliedOutfits.length;[...appliedOutfits].forEach(p=>removeOutfitSections(p.item,p.state));setAppliedOutfits([]);$('loras').innerHTML='';saveLoraState();selectLoraNote('');renderExperimentControls();promptEditorChanged();$('status').textContent=removed?'已清空 LoRA，并撤销其预设加入的提示词；手写内容已保留。':'已清空 LoRA。'}
function find(needle,list){return listOrEmpty(list).find(x=>x.toLowerCase().includes(needle.toLowerCase()))||''}
function isAnimaSelected(){return(catalog.anima_models||[]).includes($('model').value)}
function isKrea2Selected(){return(catalog.krea2_models||[]).includes($('model').value)}
function isIllustriousSelected(){const name=String($('model').value||'').replace(/\\/g,'/').toLowerCase(),file=name.split('/').pop();return!isAnimaSelected()&&!isKrea2Selected()&&(name.includes('illustrious')||file.includes('ilxl')||/^(wai|milmu|spectacular)/.test(file))}
function promptFamilyClient(){return isAnimaSelected()?'anima':isKrea2Selected()?'krea2':isIllustriousSelected()?'illustrious':'sdxl'}
function selectedLoraPayload(){return allLoraState().filter(item=>item.enabled).map(({name,weight})=>({name,weight}))}
function collectPromptSections(){return Object.fromEntries(Object.entries(PROMPT_SECTION_IDS).map(([key,id])=>[key,$(id)?.value||'']))}
function finalPromptOverride(){return{enabled:finalPromptEdited,positive:$('compiledPositive')?.value||'',negative:$('compiledNegative')?.value||''}}
