function setFinalPromptText(positive,negative,edited=false){finalPromptSyncing=true;$('compiledPositive').value=String(positive||'');$('compiledNegative').value=String(negative||'');finalPromptSyncing=false;setFinalPromptMode(edited)}
function finalPromptChanged(){if(finalPromptSyncing)return;setFinalPromptMode(true);savePromptFamilyState();clearTimeout(compileTimer);compileTimer=setTimeout(()=>compilePromptPreview().catch(()=>{}),320)}
function collectPromptState(){return{sections:collectPromptSections(),negative:$('negative').value,safetyLevel:$('safetyLevel').value,promptMode:$('promptMode').value,finalOverride:finalPromptEdited?finalPromptOverride():null}}
function savePromptFamilyState(){if(!currentPromptFamily)return;try{sessionStorage.setItem('easyPanelPromptV2:'+currentPromptFamily,JSON.stringify(collectPromptState()))}catch{}}
function restorePromptFamilyState(family){let state=null;try{state=JSON.parse(sessionStorage.getItem('easyPanelPromptV2:'+family)||'null')}catch{}if(state?.sections){Object.entries(PROMPT_SECTION_IDS).forEach(([key,id])=>{$(id).value=state.sections[key]||''});$('negative').value=state.negative||'';$('safetyLevel').value=state.safetyLevel||'safe';$('promptMode').value=state.promptMode||'style_test';if(state.finalOverride?.enabled)setFinalPromptText(state.finalOverride.positive,state.finalOverride.negative,true);else setFinalPromptMode(false)}else{setFinalPromptMode(false);applyPromptPreset('style_test',true)}syncMaturePrompt()}
function selectedTriggerListClient(){const found=[];selectedLoraPayload().forEach(lora=>{const note=loraNoteForName(lora.name),trigger=String(note.trigger||'').trim();if(trigger&&!found.some(item=>item.toLowerCase()===trigger.toLowerCase()))found.push(trigger)});return found}
function updatePromptProfileStrip(){const family=promptFamilyClient(),level=$('safetyLevel').value,name=String($('model').value||'').toLowerCase();let prefix=family==='anima'?(name.includes('aesthetic')?`masterpiece, best quality, ${level}`:`masterpiece, best quality, score_7, ${level}`):family==='krea2'?'（Krea 2 直接理解提示词，无质量前缀）':'masterpiece, best quality, highres';$('promptProfilePrefix').textContent='模型前缀：'+prefix;const triggers=selectedTriggerListClient();$('promptTriggerSummary').textContent=triggers.length?'自动触发词：'+triggers.join(' · '):'未选择带触发词的 LoRA'}
function promptCompilePayload(){return{model:$('model').value,loras:selectedLoraPayload(),prompt:'',negative:$('negative').value,promptSections:collectPromptSections(),promptMode:$('promptMode').value,safetyLevel:$('safetyLevel').value,mature:$('mature').checked,animaHardTags:$('animaHardTags').value,animaSoftPhrases:$('animaSoftPhrases').value,animaNLTags:$('animaNLTags').value,regionGlobalPrompt:$('regionGlobalPrompt')?.value||'',regions:$('regionsEnabled')?.checked?regions:[],colorCorrection:colorCorrectionPayload(),promptAutomation:promptAutomationPayload(),promptOverride:finalPromptOverride()}}
function renderPromptSources(data){const root=$('promptSources');if(!root)return;const sources=data.sources||[];root.innerHTML=sources.filter(item=>(item.terms||[]).length).map(item=>`<div class="prompt-source${item.enabled?'':' disabled'}"><b>${esc(item.label)}</b> · ${item.enabled?'启用':'关闭'}<br>${esc((item.terms||[]).join(', '))}</div>`).join('')||'<span>当前没有自动来源内容。</span>'}
