function renderPromptCompilation(data,force=false){if(force||!finalPromptEdited)setFinalPromptText(data.positive||'',data.negative||'',false);const lines=[];(data.errors||[]).forEach(item=>lines.push('错误：'+item));(data.warnings||[]).forEach(item=>lines.push('提示：'+item));if(finalPromptEdited)lines.unshift('手动原样提交：当前最终文本不会被默认词或分区内容覆盖。');$('promptDiagnostics').textContent=lines.length?lines.join('\n'):'检查通过：未发现重复、结构冲突或 LoRA 底模问题。';$('promptDiagnostics').className='small '+((data.errors||[]).length?'diagnostic-error':(data.warnings||[]).length||finalPromptEdited?'diagnostic-warning':'');$('promptCount').textContent=`${data.positiveTerms||0} 个最终标签 · ${data.negativeTerms||0} 个负面标签`;renderPromptSources(data);renderPromptDoctor(data);updatePromptProfileStrip()}
