function renderAdvancedRecommendation(){const p=currentSamplingProfile(),combos=listOrEmpty(p.combos);if($('advancedModelLabel'))$('advancedModelLabel').textContent=p.label||'当前模型';if($('advancedSource'))$('advancedSource').textContent=p.source||'';if($('advancedPresetSummary'))$('advancedPresetSummary').textContent=`自动推荐：${p.steps} 步 · CFG ${p.cfg} · ${p.sampler} / ${p.scheduler}${p.prediction&&p.prediction!=='eps'?' · '+p.prediction:''}${p.locked?'（模型锁定）':''}`;if($('advancedGuidanceNote'))$('advancedGuidanceNote').textContent=p.guidance_note||'';if($('advancedPresetButtons'))$('advancedPresetButtons').innerHTML=combos.map(c=>`<button class="secondary" type="button" title="${esc(c.note||'')}" onclick="applySamplingCombo('${esc(c.key)}')">${esc(c.label)}</button>`).join('')}
function applySamplingProfileForModel(){const p=currentSamplingProfile();$('steps').value=p.steps;$('cfg').value=p.cfg;$('sampler').value='auto';$('scheduler').value='auto';$('guidanceMode').value='off';const locked=!!p.locked;$('steps').disabled=locked;$('cfg').disabled=locked;$('sampler').disabled=locked;$('scheduler').disabled=locked;$('guidanceMode').disabled=!p.guidance_supported;if(p.hires){$('hiresScale').value=p.hires.scale;$('hiresScale').min=1;$('hiresScale').max=8;$('hiresDenoise').value=p.hires.denoise;$('hiresDenoise').min=0.05;$('hiresDenoise').max=1;$('hiresSteps').value=p.hires.steps;$('hiresSteps').min=1;$('hiresSteps').max=150;$('hiresCfg').value=p.hires.cfg;$('hiresCfg').min=1;$('hiresCfg').max=30;if($('hiresSampler'))$('hiresSampler').value=p.hires.sampler||'auto';if($('hiresScheduler'))$('hiresScheduler').value=p.hires.scheduler||'auto'}renderAdvancedRecommendation();updateSamplerBadges();guidanceChanged(true);applyDefaultHiresGenerationConfig()}
function applySamplingCombo(key){const p=currentSamplingProfile(),combo=listOrEmpty(p.combos).find(c=>c.key===key);if(!combo)return;$('steps').value=combo.steps;$('cfg').value=combo.cfg;if(!p.locked){$('sampler').value=combo.sampler;$('scheduler').value=combo.scheduler}$('guidanceMode').value=combo.guidance||'off';updateSamplerBadges();guidanceChanged();$('status').textContent=`已应用 ${p.label}「${combo.label}」：${combo.steps} 步、CFG ${combo.cfg}、${combo.sampler} / ${combo.scheduler}。${combo.note||''}`}
function loadDefaultGenerationSize(){const size=$('size'),preferred='864x1152';if(size&&[...size.options].some(option=>option.value===preferred&&!option.disabled))size.value=preferred}
function effectiveOutputSize(){const raw=String($('size')?.value||'864x1152').split('x').map(Number),baseWidth=raw[0]||864,baseHeight=raw[1]||1152,p=currentSamplingProfile(),hires=!!p.capabilities?.hires_fix&&!isAnimaSelected()&&!isKrea2Selected()&&$('illustriousMode')?.value==='hires';let scale=hires?Number($('hiresScale')?.value||p.hires?.scale||1.25):1;if(!Number.isFinite(scale))scale=1.25;scale=Math.max(1,Math.min(8,scale));const width=Math.round(baseWidth*scale/8)*8,height=Math.round(baseHeight*scale/8)*8;return{baseWidth,baseHeight,width,height,scale,hires,baseMegapixels:baseWidth*baseHeight/1e6,megapixels:width*height/1e6}}
function updateSizeInfo(){const root=$('sizeInfo');if(!root)return;const size=effectiveOutputSize();if(isIllustriousSelected()&&$('illustriousMode')?.value==='repair'){root.className='small';root.textContent='局部修复模式：成图尺寸以原图为准，请上传原图并涂出要重绘的区域。';return size}let advice='8GB 显存建议一次生成 1 张。',warning=false;if(size.hires&&size.megapixels>1.9){advice='8GB 显存风险较高：建议改用精准模式，或将放大倍率降到 1.10–1.15×。';warning=true}else if(size.megapixels>1.5){advice='8GB 通常可尝试，但请一次生成 1 张；显存不足时改用精准模式。';warning=true}else if(size.baseMegapixels>=1.2){advice='属于合理的大图范围，8GB 建议使用精准模式并一次生成 1 张。'}if(isAnimaSelected()&&size.baseMegapixels>1.25){advice='Anima 在 8GB 上生成该尺寸压力较大；若显存不足请改用 864×1152 或 1024×1024。';warning=true}else if(isKrea2Selected()&&size.baseMegapixels>1.25){advice='Krea 2 在 8GB 上生成该尺寸压力大（会走 CPU 卸载变慢）；建议 864×1152 或 1024×1024 以内。';warning=true}root.className='small'+(warning?' diagnostic-warning':'');root.textContent=`实际成图约 ${size.width} × ${size.height}（${size.megapixels.toFixed(2)} MP）。${advice}`;return size}
