function selectLoraNote(name,source=null){currentLoraName=name;currentNoteKey=noteLookupKey(name);const memo=$('loraMemo'),edit=$('memoEditButton');if(memo)memo.dataset.loraName=name||'';if(edit)edit.disabled=!name;document.querySelectorAll('#loras .lora-row').forEach(row=>row.classList.toggle('memo-active',source?row.contains(source):!!name&&row.querySelector('.lora-select')?.value===name));const badge=$('memoActiveLora');if(badge)badge.textContent=name?('当前：'+noteBaseKey(name)):'选中任一 LoRA 后显示';renderLoraMemo();promptEditorChanged()}
