const COUNT_TERMS={solo:['solo'],single:['1girl','1boy'],multi:['2girls','2boys','3girls','3boys','4girls','4boys','5girls','5boys','multiple girls','multiple boys','group','crowd','multiple people','mixed pair']};
const ALL_COUNT_TERMS=[].concat(COUNT_TERMS.solo,COUNT_TERMS.single,COUNT_TERMS.multi);
function countCategory(term){if(COUNT_TERMS.solo.includes(term))return'solo';if(COUNT_TERMS.single.includes(term))return'single';if(COUNT_TERMS.multi.includes(term))return'multi';return''}
function countTermConflicts(presetCounts,existingTerm){const cat=countCategory(existingTerm);if(!cat||presetCounts.includes(existingTerm))return false;const hasSolo=presetCounts.some(t=>countCategory(t)==='solo'),hasSingle=presetCounts.some(t=>countCategory(t)==='single'),hasMulti=presetCounts.some(t=>countCategory(t)==='multi');if(cat==='solo')return hasMulti;if(cat==='single')return hasSingle||hasMulti;if(cat==='multi')return hasSolo||hasSingle||hasMulti;return false}
function insertOutfitSections(item){const active={},added={},removed={};OUTFIT_SECTIONS.forEach(sec=>{const text=outfitSectionValue(item,sec);if(!text)return;const field=$(sec.field);if(!field)return;active[sec.key]=true;let base=splitClientTerms(field.value);const incoming=splitClientTerms(text),presetCounts=incoming.map(normalizedClientTerm).filter(t=>ALL_COUNT_TERMS.includes(t));if(presetCounts.length){const dropped=base.filter(term=>countTermConflicts(presetCounts,normalizedClientTerm(term)));if(dropped.length){removed[sec.key]=dropped;base=base.filter(term=>!dropped.includes(term))}}const known=new Set(base.map(normalizedClientTerm)),missing=incoming.filter(term=>{const key=normalizedClientTerm(term);return key&&!known.has(key)});if(missing.length||(removed[sec.key]||[]).length){const baseText=base.join(', '),newCounts=missing.filter(term=>ALL_COUNT_TERMS.includes(normalizedClientTerm(term))),newOthers=missing.filter(term=>!ALL_COUNT_TERMS.includes(normalizedClientTerm(term))),parts=[];if(newCounts.length)parts.push(newCounts.join(', '));if(baseText)parts.push(baseText);if(newOthers.length)parts.push(newOthers.join(', '));field.value=parts.join(', ');if(missing.length)added[sec.key]=missing}});return{mode:'append',active,added,removed}}
function replaceOutfitMainClass(item){const mainClass=outfitMainClass(item),matching=appliedOutfits.filter(entry=>outfitMainClass(entry.item)===mainClass);[...matching].reverse().forEach(entry=>removeOutfitSections(entry.item,entry.state));appliedOutfits=appliedOutfits.filter(entry=>outfitMainClass(entry.item)!==mainClass);const state=insertOutfitSections(item);state.mode='class-replace';state.mainClass=mainClass;state.replacedCount=matching.length;return state}
function removeOutfitSections(item,state){if(state?.mode==='overwrite'){Object.keys(state.active||{}).forEach(fieldId=>{const field=$(fieldId);if(field)field.value=String(state.base?.[fieldId]??'')});return}const added=state?.added||{},removed=state?.removed||{};OUTFIT_SECTIONS.forEach(sec=>{if(state?.active&&!state.active[sec.key])return;const field=$(sec.field);if(!field)return;let value=field.value;(added[sec.key]||[]).forEach(term=>{value=removePromptFragment(value,term)});const restore=(removed[sec.key]||[]).filter(term=>{const key=normalizedClientTerm(term);return key&&!splitClientTerms(value).some(cur=>normalizedClientTerm(cur)===key)});if(restore.length){const currentTerms=splitClientTerms(value),restoreCounts=restore.filter(t=>ALL_COUNT_TERMS.includes(normalizedClientTerm(t))),restoreOthers=restore.filter(t=>!ALL_COUNT_TERMS.includes(normalizedClientTerm(t))),currentCounts=currentTerms.filter(t=>ALL_COUNT_TERMS.includes(normalizedClientTerm(t))),currentOthers=currentTerms.filter(t=>!ALL_COUNT_TERMS.includes(normalizedClientTerm(t)));value=[].concat(restoreCounts,currentCounts,currentOthers,restoreOthers).join(', ')}field.value=value})}
function applyMemoOutfit(item){const name=String(item?.name||'未命名预设'),mainClass=outfitMainClass(item),classLabel=outfitMainClassLabel(mainClass),signature=outfitSignature(item),stateKey=noteKey(currentLoraName);if(!outfitSectionSummary(item)){$('status').textContent='该预设尚未填写任何分区内容。';return}const index=appliedOutfits.findIndex(p=>p.key===stateKey&&p.signature===signature&&activeOutfitSectionCount(p)>0);if(index>=0){removeOutfitSections(appliedOutfits[index].item,appliedOutfits[index].state);appliedOutfits.splice(index,1);setAppliedOutfits(appliedOutfits);$('status').textContent=appliedOutfits.length?`已取消「${name}」（${classLabel}）；其余 ${appliedOutfits.length} 套不同主类备忘保持不变。`:`已取消「${name}」（${classLabel}）。`}else{const state=memoOutfitOverwriteMode?replaceOutfitMainClass(item):insertOutfitSections(item);appliedOutfits.push({key:stateKey,item,signature,state});setAppliedOutfits(appliedOutfits);if(memoOutfitOverwriteMode){const labels=Object.keys(state.active||{}).map(key=>(OUTFIT_SECTIONS.find(sec=>sec.key===key)||{}).label).filter(Boolean),replaced=state.replacedCount?`，已清除之前 ${state.replacedCount} 套同主类备忘的全部分区`:'';$('status').textContent=`已载入「${name}」（${classLabel}）${replaced}；不同主类继续保留。当前载入：${labels.join('、')}。`}else{const labels=Object.keys(state.added).map(key=>(OUTFIT_SECTIONS.find(sec=>sec.key===key)||{}).label).filter(Boolean),replaced=Object.keys(state.removed).map(key=>(OUTFIT_SECTIONS.find(sec=>sec.key===key)||{}).label).filter(Boolean);let msg;if(appliedOutfits.length>1)msg=`已叠加应用「${name}」；当前共叠加 ${appliedOutfits.length} 套。`;else if(labels.length)msg=`已应用「${name}」到：${labels.join('、')}。`;else if(replaced.length)msg=`已应用「${name}」；已将${replaced.join('、')}分区原有人数标签替换为预设角色。`;else msg=`已应用「${name}」；各分区内容已存在，未重复添加。`;$('status').textContent=msg}}promptEditorChanged();renderLoraMemo();const clothing=$('promptClothing');if(clothing)clothing.focus()}
function sidecarPromptLines(content){return String(content||'').split(/\r?\n/).map(line=>line.trim()).filter(line=>line&&/[a-zA-Z]/.test(line)&&line.length<=360).filter(line=>!/^https?:/i.test(line)).filter(line=>!/^(适用底模|适用模型|用途|作者推荐|系列作者|无必填触发词|提示：|当前|本文件)/.test(line)).slice(0,18)}
function renderLoraMemo(){const display=$('memoDisplay');if(!currentNoteKey){display.textContent='尚未选择 LoRA。选中 LoRA 后会显示同名 TXT 中的触发要求。';return}const note=noteData(),outfits=Array.isArray(note.outfits)?note.outfits:[],sidecar=selectedSidecar(),triggerButton=note.trigger?`<button id="memoTriggerButton" class="token memo-trigger" type="button" title="编译器会自动锁定到最终提示词最前">已锁定触发词：${esc(note.trigger)}</button>`:'';const sidecarHtml=sidecar?`<details class="sidecar"><summary>已读取同名 TXT：${esc(sidecar.file)}${sidecar.truncated?'（已截断）':''}</summary><div class="small">点击下方英文行可按需加入提示词；原始内容仅作本地说明，不会自动加入。</div><div class="sidecar-lines" id="sidecarLines"></div><pre>${esc(sidecar.content)}</pre></details>`:`<div class="small sidecar">未找到同名 TXT 配套说明。</div>`;display.innerHTML=`<b>${esc(note.title||currentNoteKey)}</b><div class="memo-meta">${note.base_model?`<span class="tag">${esc(note.base_model)}</span>`:''}${note.weight?`<span class="tag">推荐权重 ${esc(note.weight)}</span>`:''}${triggerButton}</div>${note.url&&/^https?:\/\//.test(note.url)?`<a class="small" target="_blank" rel="noreferrer" href="${esc(note.url)}">打开 CivitAI 模型页</a>`:''}<div class="small">每套预设可指定一个主类，并携带任意分区内容；同主类跨 LoRA 自动替换，不同主类可以并存。</div><div class="memo-outfits" id="memoOutfits"></div>${sidecarHtml}`;const root=$('memoOutfits'),stateKey=noteKey(currentLoraName),trigger=$('memoTriggerButton');if(trigger)trigger.addEventListener('click',appendMemoTrigger);if(!outfits.length)root.innerHTML='<span class="small">暂无预设；点击“放大编辑”自行添加。</span>';outfits.forEach(item=>{const active=appliedOutfits.some(p=>p.key===stateKey&&p.signature===outfitSignature(item));const button=document.createElement('button');button.className='memo-outfit'+(active?' active':'');button.type='button';button.textContent=(active?'✓ ':'＋ ')+'['+outfitMainClassLabel(item)+'] '+(item.name||'未命名预设');button.title=(active?'再次点击可取消；':'同主类会替换，不同主类会保留；')+(outfitSectionSummary(item)||'（空预设）');button.onclick=()=>applyMemoOutfit(item);root.appendChild(button)});const lines=$('sidecarLines');if(lines&&sidecar){sidecarPromptLines(sidecar.content).forEach(line=>{const button=document.createElement('button');button.className='token sidecar-line';button.type='button';button.textContent='＋ '+line;button.title=line;button.onclick=()=>{appendEnglish(line,inferSectionForEnglish(line));$('tokenHint').textContent='已从 LoRA TXT 加入对应提示词分区'};lines.appendChild(button)})}}
const renderLoraMemoBase=renderLoraMemo;renderLoraMemo=function(){renderLoraMemoBase();const help=$('memoDisplay')?.querySelector(':scope > div.small:not(.sidecar)');if(help)help.textContent=memoOutfitOverwriteMode?'同主类覆盖已开启：跨 LoRA 点击新备忘时，只清除上一套同主类备忘填写的全部分区；角色、服装等不同主类可并存。':'追加模式：点击会按分区追加，同一主类也可多套并存；再次点击取消对应套。'}
function closeLoraMemoEditor(){const dialog=$('loraMemoDialog');if(dialog?.open)dialog.close();const editor=$('memoEditor');if(editor)editor.innerHTML=''}
function memoSidecarReferenceHtml(){const sidecar=selectedSidecar();if(!sidecar)return `<aside class="memo-sidecar-reference"><header><div><span class="studio-kicker">只读参考</span><h3>同名 TXT 内容</h3></div></header><div class="memo-sidecar-empty">未找到当前 LoRA 的同名 TXT。请将 TXT 放到 models\\loras 中，并与 LoRA 文件保持同名。</div></aside>`;return `<aside class="memo-sidecar-reference"><header><div><span class="studio-kicker">只读参考 · 始终显示</span><h3>${esc(sidecar.file)}</h3></div><button class="secondary" type="button" onclick="copyLoraSidecarText(this)">复制全文</button></header>${sidecar.truncated?'<div class="memo-sidecar-warning">文件较长，当前显示的是前 16000 个字符。</div>':''}<pre tabindex="0">${esc(sidecar.content)}</pre></aside>`}
async function copyLoraSidecarText(button){const sidecar=selectedSidecar();if(!sidecar)return;try{await navigator.clipboard.writeText(sidecar.content)}catch{const area=document.createElement('textarea');area.value=sidecar.content;area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();document.execCommand('copy');area.remove()}if(button){const old=button.textContent;button.textContent='已复制';setTimeout(()=>button.textContent=old,1200)}$('status').textContent='已复制当前 LoRA 的同名 TXT 内容。'}
function showMemoEditor(name=''){const selected=name||$('loraMemo')?.dataset.loraName||document.querySelector('.lora-row.memo-active .lora-select')?.value||'';if(selected){currentLoraName=selected;currentNoteKey=noteLookupKey(selected)}if(!currentNoteKey)return;const note=noteData(),editor=$('memoEditor'),dialog=$('loraMemoDialog');$('loraMemoDialogTitle').textContent='编辑 LoRA：'+noteBaseKey(currentLoraName);editor.innerHTML=`<div class="memo-editor-layout"><div class="memo-edit-scroll"><div class="two memo-overview-grid"><div><label>备忘标题</label><input id="memoTitle" value="${esc(note.title||'')}"></div><div><label>适用底模</label><input id="memoBase" value="${esc(note.base_model||'')}"></div><div><label>推荐权重</label><input id="memoWeight" value="${esc(note.weight||'')}"></div><div><label>触发词</label><input id="memoTrigger" value="${esc(note.trigger||'')}"></div></div><label>CivitAI 链接</label><input id="memoUrl" value="${esc(note.url||'')}"><label>预设内容（每套先选择主类；同主类互相覆盖，不同主类可以并存）</label><div id="memoOutfitEditor"></div><div class="actions memo-dialog-actions"><button class="secondary" type="button" onclick="addMemoOutfit()">＋ 新增预设</button><button type="button" onclick="saveLoraMemo()">保存备忘</button><button class="secondary" type="button" onclick="closeLoraMemoEditor()">取消</button></div></div>${memoSidecarReferenceHtml()}</div>`;(Array.isArray(note.outfits)?note.outfits:[]).forEach(item=>addMemoOutfit(item));if(!(note.outfits||[]).length)addMemoOutfit();if(dialog&&!dialog.open)dialog.showModal()}
function memoOutfitField(key,label,value){return `<div class="memo-section-row"><label>${label}</label><textarea class="memoOutfit${key[0].toUpperCase()+key.slice(1)}" rows="2" placeholder="${label}" oninput="syncMemoOutfitMainClass(this.closest('.memo-outfit-edit'))">${esc(value||'')}</textarea></div>`}
function memoOutfitRowData(row){const out={name:row.querySelector('.memoOutfitName')?.value.trim()||''};OUTFIT_SECTIONS.forEach(sec=>{const el=row.querySelector('.memoOutfit'+sec.key[0].toUpperCase()+sec.key.slice(1));if(el)out[sec.key]=el.value.trim()});out.main_class=outfitMainClass(out);return out}
function syncMemoOutfitMainClass(row){const label=row?.querySelector('.memoOutfitMainClass');if(label)label.textContent='主类：'+outfitMainClassLabel(memoOutfitRowData(row))+'（自动）'}
function addMemoOutfit(item={}){const root=$('memoOutfitEditor');if(!root)return;const row=document.createElement('div');row.className='memo-outfit-edit';row.innerHTML=`<div class="memo-outfit-head"><input class="memoOutfitName" placeholder="预设名称" value="${esc(item.name||'')}"><span class="memoOutfitMainClass memo-main-class" title="按从左到右、从上到下第一个有内容的分区自动判定"></span><button type="button" title="移除" onclick="this.closest('.memo-outfit-edit').remove()">×</button></div><div class="memo-outfit-grid">${OUTFIT_SECTIONS.map(sec=>memoOutfitField(sec.key,sec.label,outfitSectionValue(item,sec))).join('')}</div>`;root.appendChild(row);syncMemoOutfitMainClass(row)}
async function saveLoraMemo(){if(!currentNoteKey)return;const outfits=[...document.querySelectorAll('#memoOutfitEditor .memo-outfit-edit')].map(memoOutfitRowData).filter(item=>item.name||OUTFIT_SECTIONS.some(sec=>item[sec.key]));loraNotes[currentNoteKey]={title:$('memoTitle').value.trim(),base_model:$('memoBase').value.trim(),weight:$('memoWeight').value.trim(),trigger:$('memoTrigger').value.trim(),url:$('memoUrl').value.trim(),outfits};try{const data=await(await fetch('/api/lora-notes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({notes:loraNotes})})).json();if(data.error)throw Error(data.error);renderLoraMemo();closeLoraMemoEditor();$('status').textContent='LoRA 备忘已保存，主类已按首个有内容的分区自动分类。'}catch(e){$('status').textContent='备忘保存失败：'+e.message}}
