let depthUpload={name:'',previewUrl:''};
function initDepthControlUi(){const pose=$('poseMemo');if(!pose||$('depthMemo'))return;const panel=document.createElement('section');panel.id='depthMemo';panel.className='memo';panel.innerHTML='<div class="field-title"><h3>背景空间控制（Depth）</h3><span id="depthModelInfo" class="small">读取 Depth ControlNet…</span></div><div class="switch"><input id="depthEnabled" type="checkbox" onchange="toggleDepthControls()"><div><b>用参考图锁定背景空间</b><div class="small">人物仍由当前 Illustrious 模型与 LoRA 生成；参考图只提供透视、地面、墙体和物体远近关系。</div></div></div><div id="depthControls" style="display:none"><div class="two"><div><div class="field-title"><span>背景 / 构图参考图</span><span class="small">自动提取 Depth</span></div><input id="depthFile" type="file" accept="image/png,image/jpeg,image/webp" onchange="uploadDepthReference()"></div><div><div class="field-title"><span>Depth ControlNet</span></div><select id="depthControlnet"></select></div></div><div id="depthUploadInfo" class="small" style="margin-top:6px">尚未上传背景参考图。</div><div id="depthPreview" class="small" style="margin:8px 0"></div><div class="two"><div><div class="field-title"><span>空间约束强度</span><span class="small" title="0.45–0.65 通常既能保留空间，又不会压制人物和服装。">?</span></div><input id="depthStrength" type="number" min="0" max="2" step="0.05" value="0.55"></div><div><div class="field-title"><span>控制结束比例</span><span class="small" title="0.75 表示前 75% 采样遵循空间结构，后段让光辉模型自由补人物细节。">?</span></div><input id="depthEnd" type="number" min="0" max="1" step="0.05" value="0.75"></div></div><div class="actions"><button class="secondary" type="button" onclick="clearDepthReference()">移除参考图</button></div><p class="small">推荐链路：详细场景 Prompt + 背景 LoRA 0.4–0.6 + Depth 0.55 + 高清二采 0.35。Depth 不复制参考图人物，只约束空间结构。</p></div>';pose.after(panel);$('model')?.addEventListener('change',()=>queueMicrotask(updateDepthControlAvailability));new MutationObserver(()=>{configureDepthControlnet(catalog.controlnets||[]);updateDepthControlAvailability()}).observe($('model'),{childList:true,subtree:true});configureDepthControlnet(catalog.controlnets||[]);updateDepthControlAvailability()}
function initDepthPracticalUi(){const root=$('depthControls');if(!root||$('depthPresetButtons'))return;const presets=document.createElement('div');presets.id='depthPresetButtons';presets.className='actions';presets.style.margin='8px 0';presets.innerHTML='<button class="secondary" type="button" data-depth-preset="light" onclick="setDepthPreset(\'light\')">轻控制</button><button class="secondary active" type="button" data-depth-preset="standard" onclick="setDepthPreset(\'standard\')">标准控制</button><button class="secondary" type="button" data-depth-preset="strong" onclick="setDepthPreset(\'strong\')">强控制</button>';root.prepend(presets);const advice=document.createElement('div');advice.className='color-panel';advice.style.marginTop='8px';advice.innerHTML='<label class="switch" style="margin:0"><input id="depthSuppressSimple" type="checkbox" checked><span><b>抑制简陋背景</b><small>启用时在最终负向中明确加入 simple / plain / empty / minimal / flat / low detail background；可随时取消。</small></span></label><details style="margin-top:7px"><summary>参考图与二采建议</summary><div class="small" style="line-height:1.55;margin-top:6px">优先选择透视明确、楼梯/柱子/道路边界清晰、前中后景分明的参考图；避免严重虚化、人物占比过大或光污染遮住结构。人物镜头方向应与参考图大致一致，冲突时降低 Depth。<br>背景 LoRA 建议 0.4–0.6，复杂建筑可试 0.65，不建议一开始超过 0.7。<br>人物已好只补背景：二采 0.25–0.32；结构正确但细节弱：0.33–0.42；超过 0.45 可能改变脸、手和服装。</div></details>';root.appendChild(advice)}
function setDepthPreset(name){const presets={light:{strength:'0.45',end:'0.65',label:'轻控制：背景柔和引导，人物与镜头自由度更高。'},standard:{strength:'0.55',end:'0.75',label:'标准控制：适合商场、走廊、街区、站台和普通房间。'},strong:{strength:'0.70',end:'0.85',label:'强控制：适合巨构、后室、柱阵、楼梯和长走廊；人物姿势可能更受参考图约束。'}},preset=presets[name]||presets.standard;$('depthStrength').value=preset.strength;$('depthEnd').value=preset.end;document.querySelectorAll('[data-depth-preset]').forEach(button=>button.classList.toggle('active',button.dataset.depthPreset===name));$('depthUploadInfo').textContent=preset.label}
function configureDepthControlnet(controls){const select=$('depthControlnet');if(!select)return;const previous=select.value,items=listOrEmpty(controls);select.innerHTML=items.map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('');const depth=find('xinsir_depth',items);if(previous&&items.includes(previous))select.value=previous;else if(depth)select.value=depth}
function updateDepthControlAvailability(){const checkbox=$('depthEnabled'),info=$('depthModelInfo');if(!checkbox||!info)return;const blocked=isAnimaSelected()||isKrea2Selected(),available=!!$('depthControlnet')?.value;checkbox.disabled=blocked||!available;if(blocked){checkbox.checked=false;toggleDepthControls();info.textContent='仅支持 SDXL / Illustrious；Anima / Krea 2 不启用'}else info.textContent=available?'已找到 Depth ControlNet · 普通生图可用':'未找到 Xinsir Depth ControlNet'}
function toggleDepthControls(){$('depthControls').style.display=$('depthEnabled')?.checked?'block':'none'}
async function uploadDepthReference(){const file=$('depthFile')?.files?.[0];if(!file)return;if(file.size>20*1024*1024){$('depthUploadInfo').textContent='文件超过 20 MB，请换一张更小的参考图。';return}$('depthUploadInfo').textContent='正在上传背景参考图…';try{const form=new FormData();form.append('pose',file,file.name);const response=await fetch('/api/upload-pose',{method:'POST',body:form}),data=await response.json();if(data.error)throw Error(data.error);if(depthUpload.previewUrl)URL.revokeObjectURL(depthUpload.previewUrl);depthUpload={name:data.name,previewUrl:URL.createObjectURL(file)};$('depthUploadInfo').textContent='已上传：'+file.name;$('depthPreview').innerHTML=`<img alt="Depth 背景参考图" src="${depthUpload.previewUrl}" style="max-width:180px;max-height:180px;border-radius:8px;border:1px solid var(--line)">`}catch(error){depthUpload={name:'',previewUrl:''};$('depthUploadInfo').textContent='上传失败：'+error.message}}
function clearDepthReference(){if(depthUpload.previewUrl)URL.revokeObjectURL(depthUpload.previewUrl);depthUpload={name:'',previewUrl:''};if($('depthFile'))$('depthFile').value='';if($('depthPreview'))$('depthPreview').innerHTML='';if($('depthUploadInfo'))$('depthUploadInfo').textContent='尚未上传背景参考图。'}
function depthPayload(){if(!$('depthEnabled')?.checked)return{enabled:false};if(!depthUpload.name)throw Error('启用 Depth 后请先上传背景 / 构图参考图。');const controlnet=$('depthControlnet')?.value||'';if(!controlnet)throw Error('没有可用的 Depth ControlNet。');return{enabled:true,image:depthUpload.name,controlnet,strength:$('depthStrength').value,start:0,end:$('depthEnd').value,suppressSimple:$('depthSuppressSimple')?.checked!==false}}
function togglePoseControls(){$('poseControls').style.display=$('poseEnabled').checked?'block':'none'}
function downloadPoseEditorWorkflow(){const link=document.createElement('a');link.href='/pose-editor-workflow.json';link.download='OpenPose_Skeleton_Editor.json';document.body.appendChild(link);link.click();link.remove()}
function clearPose(){if(poseUpload.previewUrl)URL.revokeObjectURL(poseUpload.previewUrl);poseUpload={name:'',previewUrl:''};$('poseFile').value='';$('poseUploadInfo').textContent='尚未上传姿势图。';$('posePreview').innerHTML='';$('poseSkeletonPreview').innerHTML=''}
async function uploadPose(){const file=$('poseFile').files[0];if(!file)return;if(file.size>20*1024*1024){$('poseUploadInfo').textContent='文件超过 20 MB，请换一张更小的姿势图。';return}$('poseUploadInfo').textContent='正在上传姿势图…';try{const form=new FormData();form.append('pose',file,file.name);const response=await fetch('/api/upload-pose',{method:'POST',body:form}),data=await response.json();if(data.error)throw Error(data.error);if(poseUpload.previewUrl)URL.revokeObjectURL(poseUpload.previewUrl);poseUpload={name:data.name,previewUrl:URL.createObjectURL(file)};$('poseUploadInfo').textContent='已上传：'+file.name;$('posePreview').innerHTML=`<img alt="姿势参考预览" src="${poseUpload.previewUrl}" style="max-width:180px;max-height:180px;border-radius:8px;border:1px solid var(--line)">`;$('poseSkeletonPreview').innerHTML=''}catch(e){poseUpload.name='';$('poseUploadInfo').textContent='上传失败：'+e.message}}
function extractModeLabel(mode){return{auto:'自动','dwpose-full':'DWPose·整图','dwpose-yolo':'DWPose·人体检测',openpose:'OpenPose·备用'}[mode]||mode}
