window.EasyPanelSharedStateBridge={storageKeys:{promptPresets:'easyPanelPromptPresetsV1',characterFavorites:'easyPanelLoraFavoritesV1'},read(){return{promptPresets:JSON.parse(JSON.stringify(userPromptPresets||[])),characterFavorites:[...(loraFavorites||new Set())].sort()}},write(state){const promptPresets=Array.isArray(state?.promptPresets)?state.promptPresets.map(normalizeUserPromptPreset).filter(item=>item.name&&item.content).slice(0,1000):[];const characterFavorites=Array.isArray(state?.characterFavorites)?state.characterFavorites.filter(name=>typeof name==='string'&&name.trim()).map(name=>name.trim().replace(/\\/g,'/')).filter((name,index,array)=>array.indexOf(name)===index).sort():[];userPromptPresets=promptPresets;persistUserPromptPresets();loraFavorites=new Set(characterFavorites);saveLoraFavorites();renderUserPromptPresets();if($('loraFolder')){renderLoraFolderOptions();refreshLoraSelects()}return this.read()}};

/* ===== Mobile advanced-panel session keep (mobile=1 only) =====
 * The native Android advanced panel recreates its WebView each time it is
 * reopened, so this module snapshots the whole generation form plus the job
 * queue into localStorage and restores it right after the model catalogue is
 * ready.  Switching to the quick screen / library and back then looks exactly
 * like the panel was never re-initialised.  Desktop pages are untouched. */
const MOBILE_PANEL_STATE_KEY='easyPanelMobilePersistV1';
function mobilePanelMode(){return /(?:^|[?&])mobile=1(?:&|$)/.test(String(location.search||''))}
function mobilePanelSnapshot(){try{return JSON.stringify({savedAt:Date.now(),payload:payload(),jobQueue:jobQueue.slice(0,MAX_LOGICAL_JOBS)})}catch{return null}}
function saveMobilePanelState(){if(!mobilePanelMode())return;const text=mobilePanelSnapshot();if(text==null)return;try{localStorage.setItem(MOBILE_PANEL_STATE_KEY,text)}catch{}}
function loadMobileJobQueue(){if(!mobilePanelMode())return;let raw=null;try{raw=localStorage.getItem(MOBILE_PANEL_STATE_KEY)}catch{return}if(!raw)return;let data=null;try{data=JSON.parse(raw)}catch{return}if(data&&Array.isArray(data.jobQueue)&&data.jobQueue.length&&!jobQueue.length){jobQueue=data.jobQueue.slice(0,MAX_LOGICAL_JOBS);renderJobQueue()}}
function restoreMobilePanelState(){if(!mobilePanelMode())return;let raw=null;try{raw=localStorage.getItem(MOBILE_PANEL_STATE_KEY)}catch{return}if(!raw)return;let data=null;try{data=JSON.parse(raw)}catch{return}if(!data||!data.payload||typeof data.payload!=='object')return;const apply=()=>{if($('model')?.options.length){try{restorePayloadToPanel(data.payload)}catch{}}};if($('model')?.options.length){apply()}else{let tries=0;const timer=setInterval(()=>{tries++;if($('model')?.options.length){clearInterval(timer);apply()}else if(tries>=20){clearInterval(timer)}},500)}}
function startMobilePanelKeep(){if(!mobilePanelMode()||window.__easyPanelMobileKeepStarted)return;window.__easyPanelMobileKeepStarted=true;const save=()=>saveMobilePanelState();window.addEventListener('pagehide',save);window.addEventListener('beforeunload',save);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')save()});setInterval(save,4000);loadMobileJobQueue();restoreMobilePanelState();window.__easyPanelClearMobileKeep=()=>{try{localStorage.removeItem(MOBILE_PANEL_STATE_KEY)}catch{}saveMobilePanelState()}}
startMobilePanelKeep();
